return ['domain'=>'radioedu-conecta','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'eu','project-id-version'=>'RadioEdu Conecta 1.2','pot-creation-date'=>'2026-10-31T15:33:36+00:00','po-revision-date'=>'2026-11-01 00:30+0100','x-generator'=>'WP-CLI 2.12.0','messages'=>['RadioEdu Conecta'=>'RadioEdu Conecta','https://radioedu.educarex.es/conecta'=>'https://radioedu.educarex.es/conecta','Directorio interactivo y sistema colaborativo ("Traspasando Fronteras") para la red de radios escolares de Extremadura y del mundo.'=>'Direktorio interaktiboa eta lankidetza-sistema ("Traspasando Fronteras"), Extremadurako eta munduko eskola-irratien sarearentzat.','RadioEdu - Consejería de Educación, Ciencia y Formación Profesional (Junta de Extremadura)'=>'RadioEdu - Consejería de Educación, Ciencia y Formación Profesional (Junta de Extremadura)','https://radioedu.educarex.es'=>'https://radioedu.educarex.es','RadioEdu Conecta requires PHP version %1$s or higher. Your server is running PHP %2$s.'=>'RadioEdu Conectak PHP %1$s edo berriagoa behar du. Zure zerbitzariak PHP %2$s erabiltzen du.','RadioEdu Conecta requires WordPress %1$s or higher. You are using WordPress %2$s.'=>'RadioEdu Conectak WordPress %1$s edo berriagoa behar du. WordPress %2$s erabiltzen ari zara.','Ajustes'=>'Ezarpenak','-- Selecciona región o país --'=>'-- Hautatu eskualdea edo herrialdea --','Extremadura (España)'=>'Extremadura (Espainia)','Andalucía (España)'=>'Andaluzia (Espainia)','Aragón (España)'=>'Aragoi (Espainia)','Asturias (España)'=>'Asturias (Espainia)','Cantabria (España)'=>'Kantabria (Espainia)','Castilla y León (España)'=>'Gaztela eta Leon (Espainia)','Castilla-La Mancha (España)'=>'Gaztela-Mantxa (Espainia)','Cataluña (España)'=>'Katalunia (Espainia)','Comunidad Valenciana (España)'=>'Valentziako Erkidegoa (Espainia)','Galicia (España)'=>'Galizia (Espainia)','Islas Baleares (España)'=>'Balear Uharteak (Espainia)','Islas Canarias (España)'=>'Kanariak (Espainia)','La Rioja (España)'=>'Errioxa (Espainia)','Madrid (España)'=>'Madril (Espainia)','Murcia (España)'=>'Murtzia (Espainia)','Navarra (España)'=>'Nafarroa (Espainia)','País Vasco (España)'=>'Euskadi (Espainia)','España (General)'=>'Espainia (orokorra)','Portugal'=>'Portugal','Francia'=>'Frantzia','Italia'=>'Italia','Irlanda'=>'Irlanda','Reino Unido'=>'Erresuma Batua','Alemania'=>'Alemania','Unión Europea / Internacional'=>'Europar Batasuna / Nazioartekoa','México'=>'Mexiko','Argentina'=>'Argentina','Colombia'=>'Kolonbia','Chile'=>'Txile','Otro / Internacional'=>'Beste bat / Nazioartekoa','Datos de la Emisora y Coordinación (Traspasando Fronteras)'=>'Irratiaren eta koordinazioaren datuak (Traspasando Fronteras)','Logo de la Radio Escolar'=>'Eskola-irratiaren logoa','Logo de la radio'=>'Irratiaren logoa','No hay logo asignado. Se mostrará un icono por defecto.'=>'Ez dago logorik esleituta. Ikono lehenetsi bat erakutsiko da.','Subir / Elegir Logo'=>'Igo / Aukeratu logoa','Eliminar logo'=>'Kendu logoa','Imagen circular distintiva de la emisora escolar (recomendado 300x300 px formato PNG o JPG).'=>'Eskola-irratia bereizten duen irudi biribila (300x300 px gomendatzen da, PNG edo JPG formatuan).','Bandera / Región'=>'Bandera / Eskualdea','Determina la bandera mostrada en la tarjeta de resultados y filtros geográficos.'=>'Emaitzen txartelean eta iragazki geografikoetan erakusten den bandera zehazten du.','Coordenadas para el Mapa'=>'Maparako koordenatuak','Latitud:'=>'Latitudea:','Longitud:'=>'Longitudea:','Coordenadas decimales para ubicar el centro en el mapa interactivo (ej. Cáceres: 39.4699, -6.3708).'=>'Ikastetxea mapa interaktiboan kokatzeko koordenatu hamartarrak (adib. Cáceres: 39.4699, -6.3708).','URL de Podcast / Streaming'=>'Podcastaren / streamingaren URLa','Enlace donde se pueden escuchar las grabaciones o emisiones del centro escolar.'=>'Ikastetxeko grabazioak edo emisioak entzuteko esteka.','Web Oficial del Centro'=>'Ikastetxearen webgune ofiziala','Cursos / Edades del Alumnado'=>'Ikasleen mailak / adinak','Informa a otros centros sobre el grupo de edad de los alumnos que participan en la radio.'=>'Irratian parte hartzen duten ikasleen adin-taldearen berri ematen die beste ikastetxeei.','Coordinador/a Responsable'=>'Koordinatzaile arduraduna','Nombre del docente coordinador'=>'Irakasle koordinatzailearen izena','Email:'=>'Helbide elektronikoa:','Aviso de Privacidad (RGPD):'=>'Pribatutasun-oharra (DBEO):','El correo NO se publicará en el directorio público. Se emplea exclusivamente para avisos internos del sistema cuando otro centro envíe una propuesta de colaboración.'=>'Helbide elektronikoa EZ da direktorio publikoan argitaratuko. Sistemaren barne-abisuetarako soilik erabiltzen da, beste ikastetxe batek lankidetza-proposamen bat bidaltzen duenean.','Estado de Colaboración'=>'Lankidetza-egoera','Disponible para recibir propuestas de match y proyectos conjuntos'=>'Match proposamenak eta proiektu bateratuak jasotzeko prest','Propuestas de Colaboración (Matches)'=>'Lankidetza-proposamenak (matchak)','Colaboraciones (Matches)'=>'Lankidetzak (matchak)','No tienes permisos para realizar esta acción.'=>'Ez duzu ekintza hau egiteko baimenik.','Parámetros de respuesta no válidos.'=>'Erantzunaren parametroak ez dira baliozkoak.','No tienes permisos para responder a las propuestas de este centro.'=>'Ez duzu ikastetxe honen proposamenei erantzuteko baimenik.','No tienes permisos suficientes para acceder a esta página.'=>'Ez duzu orri honetara sartzeko behar adina baimenik.','Propuestas de Colaboración (Matches) - Traspasando Fronteras'=>'Lankidetza-proposamenak (matchak) - Traspasando Fronteras','Consulta las solicitudes de hermanamiento recibidas o enviadas por tu emisora escolar y coordina proyectos conjuntos.'=>'Kontsultatu zure eskola-irratiak jaso edo bidalitako senidetze-eskaerak eta koordinatu proiektu bateratuak.','La respuesta a la propuesta de colaboración se ha guardado correctamente y se ha notificado al centro emisor.'=>'Lankidetza-proposamenaren erantzuna behar bezala gorde da, eta ikastetxe igorleari jakinarazi zaio.','Todavía no hay propuestas de colaboración registradas para tus centros escolares.'=>'Oraindik ez dago lankidetza-proposamenik erregistratuta zure ikastetxeentzat.','Fecha'=>'Data','Centro Emisor'=>'Ikastetxe igorlea','Centro Receptor'=>'Ikastetxe hartzailea','Idea del Proyecto y Detalles'=>'Proiektuaren ideia eta xehetasunak','Estado'=>'Egoera','Respuesta / Acciones'=>'Erantzuna / ekintzak','Edades:'=>'Adinak:','Idiomas:'=>'Hizkuntzak:','Fechas:'=>'Datak:','Aceptada'=>'Onartua','Declinada'=>'Baztertua','Pendiente'=>'Zain','Mensaje de respuesta'=>'Erantzun-mezua','Escribe un mensaje para el centro emisor...'=>'Idatzi mezu bat ikastetxe igorlearentzat...','Aceptar'=>'Onartu','Declinar'=>'Baztertu','En espera de respuesta del centro receptor.'=>'Ikastetxe hartzailearen erantzunaren zain.','RadioEdu Conecta: fichas de la red'=>'RadioEdu Conecta: sareko fitxak','Nombre del sitio'=>'Gunearen izena','Nombre del centro'=>'Ikastetxearen izena','Sí'=>'Bai','URL del sitio'=>'Gunearen URLa','Web oficial'=>'Webgune ofiziala','Icono del sitio'=>'Gunearen ikonoa','Logo'=>'Logoa','Descripción corta'=>'Deskribapen laburra','Descripción'=>'Deskribapena','Solo al crearla'=>'Sortzean soilik','Email de administración'=>'Administrazioko helbide elektronikoa','Email del coordinador/a'=>'Koordinatzailearen helbide elektronikoa','Administrador del sitio'=>'Gunearen administratzailea','Autor de la ficha'=>'Fitxaren egilea','Crea en el directorio del sitio principal una ficha de radio para el %d sitio de la red, o actualiza la que ya tiene.'=>'Gune nagusiaren direktorioan irrati-fitxa bat sortzen du sareko %d gunerako, edo lehendik duena eguneratzen du.' . "\0" . 'Gune nagusiaren direktorioan irrati-fitxa bat sortzen du sareko %d guneetako bakoitzerako, edo lehendik dutena eguneratzen du.','Datos que la sincronización toma de cada sitio'=>'Sinkronizazioak gune bakoitzetik hartzen dituen datuak','Del sitio'=>'Gunetik','A la ficha'=>'Fitxara','¿Se actualiza al volver a sincronizar?'=>'Berriro sinkronizatzean eguneratzen da?','Lo que el coordinador complete después (coordenadas, bandera, etapas, idiomas, temas y podcast) no se modifica nunca. Si ya existe una ficha creada a mano con la misma web, se reutiliza. Las fichas en la papelera no se tocan. Las fichas de sitios que ya no existen no se borran: aparecen en el resumen.'=>'Koordinatzaileak geroago betetzen duena (koordenatuak, bandera, etapak, hizkuntzak, gaiak eta podcasta) ez da inoiz aldatzen. Webgune bera duen eskuz sortutako fitxa bat badago, berrerabili egiten da. Zakarrontziko fitxak ez dira ukitzen. Jada existitzen ez diren guneen fitxak ez dira ezabatzen: laburpenean agertzen dira.','Dar el rol Autor en el sitio principal a los autores de las fichas que no lo tengan, ni tengan otro superior, para que puedan editar su ficha.'=>'Eman Egilea rola gune nagusian rol hori edo goragoko bat ez duten fitxen egileei, beren fitxa editatu ahal izan dezaten.','Sincronizar fichas con los sitios de la red'=>'Sinkronizatu fitxak sareko guneekin','La sincronización necesita JavaScript.'=>'Sinkronizazioak JavaScript behar du.','Progreso de la sincronización'=>'Sinkronizazioaren aurrerapena','Ajustes de RadioEdu Conecta'=>'RadioEdu Conectaren ezarpenak','Configuración del Mapa Interactivo'=>'Mapa interaktiboaren konfigurazioa','Define el centro geográfico y nivel de zoom inicial al abrir la vista de mapa en el directorio.'=>'Direktorioko mapa-ikuspegia irekitzean erabiliko diren erdigune geografikoa eta hasierako zoom-maila zehazten ditu.','Centro del mapa (Latitud / Longitud)'=>'Maparen erdigunea (latitudea / longitudea)','Notificaciones por Correo Electrónico'=>'Posta elektroniko bidezko jakinarazpenak','Gestiona las notificaciones automáticas enviadas a los docentes coordinadores de las emisoras.'=>'Irratietako irakasle koordinatzaileei bidaltzen zaizkien jakinarazpen automatikoak kudeatzen ditu.','Avisos automáticos'=>'Abisu automatikoak','Coordinadores'=>'Koordinatzaileak','Controla cuántas radios puede dar de alta cada coordinador (rol Autor). Los administradores y editores no tienen límite.'=>'Koordinatzaile bakoitzak (Egilea rola) zenbat irrati sor ditzakeen kontrolatzen du. Administratzaileek eta editoreek ez dute mugarik.','Radios por usuario'=>'Irratiak erabiltzaileko','El número de radios por usuario debe ser un número entero igual o mayor que 0, o quedar vacío. Se mantiene el valor anterior.'=>'Erabiltzaileko irrati kopuruak 0 edo handiagoa den zenbaki oso bat izan behar du, edo hutsik egon. Aurreko balioa mantentzen da.','Lat:'=>'Lat:','Lng:'=>'Lng:','Zoom inicial (1-18):'=>'Hasierako zooma (1-18):','Por defecto centrado en Extremadura (39.4699, -6.3708, zoom 8).'=>'Lehenespenez, Extremaduran zentratuta (39.4699, -6.3708, 8 zooma).','Notificar por correo al coordinador del centro receptor cuando reciba una nueva propuesta de colaboración.'=>'Bidali mezu elektroniko bat ikastetxe hartzailearen koordinatzaileari lankidetza-proposamen berri bat jasotzen duenean.','Notificar por correo al coordinador emisor cuando su propuesta sea aceptada o rechazada.'=>'Bidali mezu elektroniko bat koordinatzaile igorleari bere proposamena onartu edo baztertzen denean.','Número máximo de radios que puede crear cada coordinador. Déjalo vacío para no poner límite. Con 0 no pueden crear ninguna y solo editan las que les asigne un administrador. Las radios en la papelera no cuentan.'=>'Koordinatzaile bakoitzak sor ditzakeen irratien gehienezko kopurua. Utzi hutsik mugarik ez jartzeko. 0 jarrita, ezin dute bat ere sortu, eta administratzaile batek esleitzen dizkienak soilik edita ditzakete. Zakarrontziko irratiak ez dira zenbatzen.','Configuración global del directorio de radios escolares Traspasando Fronteras.'=>'Traspasando Fronteras eskola-irratien direktorioaren konfigurazio orokorra.','¡Se han cargado o sincronizado con éxito %d emisoras de ejemplo con sus imágenes, taxonomías y coordenadas en el mapa!'=>'Adibideko %d irrati behar bezala kargatu edo sinkronizatu dira, beren irudi, taxonomia eta mapako koordenatuekin!','Emisoras de Demostración (Traspasando Fronteras)'=>'Adibideko irratiak (Traspasando Fronteras)','El instalador incluye 6 emisoras completas de ejemplo con fotografías de cabecera, logotipos, edades, formatos, idiomas y coordenadas geográficas. Puedes volver a generarlas o sincronizarlas en cualquier momento con este botón:'=>'Instalatzaileak adibideko 6 irrati oso ditu, goiburuko argazki, logo, adin, formatu, hizkuntza eta koordenatu geografikoekin. Botoi honekin edozein unetan sor edo sinkroniza ditzakezu berriro:','Sincronizar / Cargar las 6 emisoras de ejemplo'=>'Sinkronizatu / Kargatu adibideko 6 irratiak','Las radios las da de alta un administrador. Puedes editar las que tengas asignadas.'=>'Irratiak administratzaile batek sortzen ditu. Esleituta dituzunak edita ditzakezu.','Has alcanzado el máximo de %d radio por usuario. Para dar de alta otra, contacta con un administrador.'=>'Erabiltzaileko %d irratiko mugara iritsi zara. Beste bat sortzeko, jarri harremanetan administratzaile batekin.' . "\0" . 'Erabiltzaileko %d irratiko mugara iritsi zara. Beste bat sortzeko, jarri harremanetan administratzaile batekin.','[RadioEdu Traspasando Fronteras] ¡Nueva propuesta de match de %s!'=>'[RadioEdu Traspasando Fronteras] Match proposamen berria: %s','Hola,'=>'Kaixo:','El centro escolar "%1$s" ha seleccionado vuestra emisora ("%2$s") para proponer un proyecto de colaboración en la red Traspasando Fronteras.'=>'"%1$s" ikastetxeak zuen irratia ("%2$s") hautatu du Traspasando Fronteras sarean lankidetza-proiektu bat proposatzeko.','Idea del proyecto propuesta:'=>'Proposatutako proiektuaren ideia:','Cursos/Edades: %s'=>'Mailak/adinak: %s','No especificado'=>'Zehaztu gabe','Fechas previstas: %s'=>'Aurreikusitako datak: %s','Por acordar'=>'Adosteko','Puedes consultar todos los detalles y responder a la propuesta accediendo al panel de RadioEdu:'=>'Xehetasun guztiak kontsultatu eta proposamenari erantzun diezaiokezu RadioEduren panelean:','RadioEdu Conecta - Red de Radios Escolares de Extremadura y del Mundo'=>'RadioEdu Conecta - Extremadurako eta munduko eskola-irratien sarea','ACEPTADA'=>'ONARTUA','DECLINADA'=>'BAZTERTUA','[RadioEdu Traspasando Fronteras] Tu propuesta a %1$s ha sido %2$s'=>'[RadioEdu Traspasando Fronteras] %1$s ikastetxeari egindako zure proposamena %2$s izan da','Te informamos de que la propuesta de colaboración enviada por "%1$s" al centro "%2$s" ha sido marcada como: %3$s.'=>'Jakinarazten dizugu "%1$s" ikastetxeak "%2$s" ikastetxeari bidalitako lankidetza-proposamena honela markatu dela: %3$s.','Mensaje o indicaciones del centro:'=>'Ikastetxearen mezua edo argibideak:','Sin mensaje adicional.'=>'Ez dago mezu gehigarririk.','Contacto de coordinación de la emisora: %1$s <%2$s>'=>'Irratiaren koordinazio-kontaktua: %1$s <%2$s>','Puedes acceder a la plataforma para coordinar los siguientes pasos con la emisora.'=>'Plataformara sar zaitezke, irratiarekin hurrengo urratsak koordinatzeko.','RadioEdu Conecta - Traspasando Fronteras'=>'RadioEdu Conecta - Traspasando Fronteras','Ficha de centro de radio'=>'Irrati-ikastetxearen fitxa','Perfil público de un centro: cabecera y pie del tema alrededor de la ficha, sin repetir su título, autor, fecha ni imagen de cabecera.'=>'Ikastetxe baten profil publikoa: gaiaren goiburua eta orri-oina fitxaren inguruan, haren izenburua, egilea, data eta goiburuko irudia errepikatu gabe.','Iconos del directorio de radios escolares Traspasando Fronteras.'=>'Traspasando Fronteras eskola-irratien direktorioaren ikonoak.','Cerrar'=>'Itxi','Globo terráqueo'=>'Lur-globoa','Birrete de graduación'=>'Graduazio-txanoa','Auriculares'=>'Entzungailuak','Centro educativo'=>'Ikastetxea','Mapa'=>'Mapa','Micrófono'=>'Mikrofonoa','Enviar'=>'Bidali','El sitio no existe.'=>'Gunea ez da existitzen.','ID del adjunto de imagen usado como logo de la emisora.'=>'Irratiaren logo gisa erabiltzen den irudi-eranskinaren IDa.','URL del logo de los centros de demostración.'=>'Adibideko ikastetxeen logoaren URLa.','URL de la imagen de cabecera de los centros de demostración.'=>'Adibideko ikastetxeen goiburuko irudiaren URLa.','Código de la bandera o región mostrada en el directorio.'=>'Direktorioan erakusten den banderaren edo eskualdearen kodea.','Latitud decimal del centro en el mapa.'=>'Ikastetxearen latitude hamartarra mapan.','Longitud decimal del centro en el mapa.'=>'Ikastetxearen longitude hamartarra mapan.','URL del podcast o de la emisión en directo.'=>'Podcastaren edo zuzeneko emisioaren URLa.','URL de la web oficial del centro.'=>'Ikastetxearen webgune ofizialaren URLa.','Cursos o edades del alumnado que participa en la radio.'=>'Irratian parte hartzen duten ikasleen mailak edo adinak.','Nombre del coordinador o coordinadora (dato personal, privado).'=>'Koordinatzailearen izena (datu pertsonala, pribatua).','Email del coordinador o coordinadora (dato personal, privado).'=>'Koordinatzailearen helbide elektronikoa (datu pertsonala, pribatua).','Disponibilidad para recibir propuestas: "1" disponible, "0" no disponible.'=>'Proposamenak jasotzeko prestasuna: "1" prest, "0" ez prest.','Marca los contenidos creados por el importador de demostración.'=>'Adibideen inportatzaileak sortutako edukiak markatzen ditu.','ID del sitio de la red del que la sincronización de red tomó los datos de la ficha.'=>'Sareko sinkronizazioak fitxaren datuak zein sareko gunetatik hartu zituen, gune horren IDa.','El logo debe ser una imagen de la biblioteca de medios a la que tengas acceso.'=>'Logoak sarbidea duzun multimedia-liburutegiko irudi bat izan behar du.','Post type general nameCentros y Radios'=>'Ikastetxeak eta irratiak','Post type singular nameCentro de Radio'=>'Irrati-ikastetxea','Admin Menu textRadioEdu Centros'=>'RadioEdu Ikastetxeak','Add New on ToolbarCentro de Radio'=>'Irrati-ikastetxea','Añadir nuevo centro'=>'Gehitu ikastetxe berria','Añadir nuevo centro de radio'=>'Gehitu irrati-ikastetxe berria','Nuevo centro'=>'Ikastetxe berria','Editar centro de radio'=>'Editatu irrati-ikastetxea','Ver ficha de centro'=>'Ikusi ikastetxearen fitxa','Todos los centros'=>'Ikastetxe guztiak','Buscar centros de radio'=>'Bilatu irrati-ikastetxeak','Centro superior:'=>'Ikastetxe gurasoa:','No se encontraron centros.'=>'Ez da ikastetxerik aurkitu.','No hay centros en la papelera.'=>'Ez dago ikastetxerik zakarrontzian.','Overrides the "Featured Image" phraseFoto de cabecera / Fachada del centro'=>'Goiburuko argazkia / Ikastetxearen fatxada','Overrides the "Set featured image" phraseAsignar foto de cabecera'=>'Ezarri goiburuko argazkia','Overrides the "Remove featured image" phraseQuitar foto de cabecera'=>'Kendu goiburuko argazkia','Overrides the "Use as featured image" phraseUsar como foto de cabecera'=>'Erabili goiburuko argazki gisa','The post type archive labelDirectorio de radios escolares'=>'Eskola-irratien direktorioa','The post type attributes labelAtributos de centro'=>'Ikastetxearen atributuak','Overrides the "Insert into post" phraseInsertar en la ficha de centro'=>'Txertatu ikastetxearen fitxan','Overrides the "Uploaded to this post" phraseSubido a este centro'=>'Ikastetxe honetara igota','Screen reader text for the filter linksFiltrar lista de centros'=>'Iragazi ikastetxeen zerrenda','Screen reader text for the paginationNavegación de lista de centros'=>'Ikastetxeen zerrendaren nabigazioa','Screen reader text for the items listLista de centros'=>'Ikastetxeen zerrenda','RadioEdu Conecta (Traspasando Fronteras)'=>'RadioEdu Conecta (Traspasando Fronteras)','Este sitio utiliza el plugin RadioEdu Conecta para gestionar el directorio de radios escolares. Los datos de contacto del docente coordinador (nombre y correo electrónico profesional) se almacenan de forma interna y nunca se exponen públicamente en el directorio web ni en las respuestas públicas de la API REST.'=>'Gune honek RadioEdu Conecta plugina erabiltzen du eskola-irratien direktorioa kudeatzeko. Irakasle koordinatzailearen harremanetarako datuak (izena eta laneko helbide elektronikoa) barnean gordetzen dira, eta ez dira inoiz publikoki erakusten web-direktorioan, ezta REST APIaren erantzun publikoetan ere.','Al activar voluntariamente la vista de mapa interactivo, el navegador del usuario se conecta con los servidores de OpenStreetMap Foundation para descargar la cartografía.'=>'Mapa interaktiboaren ikuspegia borondatez aktibatzean, erabiltzailearen nabigatzailea OpenStreetMap Foundation-en zerbitzariekin konektatzen da kartografia deskargatzeko.','Los centros marcados como favoritos y la aceptación del mapa se guardan únicamente en el almacenamiento local del navegador del visitante y no se envían al servidor.'=>'Gogoko gisa markatutako ikastetxeak eta maparen onarpena bisitariaren nabigatzailearen biltegiratze lokalean soilik gordetzen dira, eta ez dira zerbitzarira bidaltzen.','RadioEdu Conecta (Coordinadores y Propuestas)'=>'RadioEdu Conecta (koordinatzaileak eta proposamenak)','RadioEdu Conecta - Coordinación de Centros'=>'RadioEdu Conecta - Ikastetxeen koordinazioa','Centro escolar'=>'Ikastetxea','Nombre del coordinador'=>'Koordinatzailearen izena','Email de coordinación'=>'Koordinazioko helbide elektronikoa','RadioEdu Conecta - Propuestas de Colaboración'=>'RadioEdu Conecta - Lankidetza-proposamenak','Centro emisor'=>'Ikastetxe igorlea','Centro receptor'=>'Ikastetxe hartzailea','Cursos / Edades'=>'Mailak / adinak','Idiomas'=>'Hizkuntzak','Fechas aproximadas'=>'Gutxi gorabeherako datak','Respuesta'=>'Erantzuna','Idea de proyecto'=>'Proiektuaren ideia','Se han eliminado los textos enviados y la vinculación con la cuenta. Los centros, las fechas, el estado y las respuestas de otros participantes se conservan como historial compartido; revise esas respuestas si contienen datos personales de la persona solicitante.'=>'Bidalitako testuak eta kontuarekiko lotura ezabatu dira. Ikastetxeak, datak, egoera eta beste parte-hartzaile batzuen erantzunak historia partekatu gisa gordetzen dira; berrikusi erantzun horiek, eskatzailearen datu pertsonalik ba ote duten jakiteko.','No se han podido eliminar todos los datos. Reintente la solicitud de borrado.'=>'Ezin izan dira datu guztiak ezabatu. Egin berriro ezabatze-eskaera.','Número de página de resultados.'=>'Emaitzen orri-zenbakia.','Número de centros por página.'=>'Orri bakoitzeko ikastetxe kopurua.','Término de búsqueda por nombre o palabra clave.'=>'Izenaren edo gako-hitzaren araberako bilaketa-terminoa.','Criterio de ordenación.'=>'Ordenatzeko irizpidea.','ID del centro de referencia para calcular afinidad.'=>'Afinitatea kalkulatzeko erreferentziako ikastetxearen IDa.','Slug de etapa educativa.'=>'Hezkuntza-etaparen slug-a.','Slug de idioma.'=>'Hizkuntzaren slug-a.','Slug de temática.'=>'Gaiaren slug-a.','Slug de formato de programa.'=>'Programa-formatuaren slug-a.','Slug de ubicación geográfica.'=>'Kokapen geografikoaren slug-a.','ID de la propuesta de colaboración.'=>'Lankidetza-proposamenaren IDa.','Nuevo estado de la propuesta.'=>'Proposamenaren egoera berria.','Mensaje de respuesta para el centro emisor.'=>'Ikastetxe igorlearentzako erantzun-mezua.','Has alcanzado el límite de propuestas por hora. Por favor, inténtalo más tarde.'=>'Orduko proposamen-mugara iritsi zara. Saiatu berriro geroago.','No puedes enviar una propuesta de colaboración a tu propio centro escolar.'=>'Ezin diozu zure ikastetxeari lankidetza-proposamenik bidali.','Por favor, describe brevemente la idea del proyecto conjunto.'=>'Deskribatu laburki proiektu bateratuaren ideia.','Uno de los centros especificados no es válido o no está publicado.'=>'Zehaztutako ikastetxeetako bat ez da baliozkoa edo ez dago argitaratuta.','No tienes permisos para enviar propuestas en nombre del centro emisor seleccionado.'=>'Ez duzu hautatutako ikastetxe igorlearen izenean proposamenak bidaltzeko baimenik.','Este centro escolar no está disponible actualmente para recibir nuevas propuestas de colaboración.'=>'Ikastetxe hau ez dago une honetan lankidetza-proposamen berriak jasotzeko prest.','No se pudo registrar la propuesta en la base de datos.'=>'Ezin izan da proposamena datu-basean erregistratu.','¡Propuesta de match enviada con éxito! La emisora receptora recibirá una notificación para comenzar a coordinar el proyecto.'=>'Match proposamena bidali da! Irrati hartzaileak jakinarazpen bat jasoko du proiektua koordinatzen hasteko.','Estado de la colaboración actualizado correctamente.'=>'Lankidetzaren egoera behar bezala eguneratu da.','El estado indicado no es válido.'=>'Adierazitako egoera ez da baliozkoa.','La propuesta de colaboración no existe.'=>'Lankidetza-proposamena ez da existitzen.','El mensaje de respuesta es demasiado largo.'=>'Erantzun-mezua luzeegia da.','Esta propuesta ya ha sido respondida y no puede modificarse.'=>'Proposamen honi dagoeneko erantzun zaio, eta ezin da aldatu.','ID del centro que envía la propuesta.'=>'Proposamena bidaltzen duen ikastetxearen IDa.','ID del centro que recibe la propuesta.'=>'Proposamena jasotzen duen ikastetxearen IDa.','Idea del proyecto conjunto.'=>'Proiektu bateratuaren ideia.','Curso o edades del alumnado participante.'=>'Parte hartzen duten ikasleen maila edo adinak.','Idiomas de trabajo del proyecto.'=>'Proiektuaren lan-hizkuntzak.','Fechas aproximadas del proyecto.'=>'Proiektuaren gutxi gorabeherako datak.','Número de sitios ya procesados.'=>'Dagoeneko prozesatutako gune kopurua.','Si los autores de las fichas reciben el rol Autor en el sitio principal. Si se omite, se usa la última elección.'=>'Fitxen egileek gune nagusian Egilea rola jasotzen duten ala ez. Adierazten ez bada, azken aukera erabiltzen da.','La sincronización de red solo funciona en el sitio principal de una red multisitio.'=>'Sareko sinkronizazioak gune anitzeko sare baten gune nagusian soilik funtzionatzen du.','No tienes permiso para sincronizar las fichas de la red.'=>'Ez duzu sareko fitxak sinkronizatzeko baimenik.','Sitios procesados en este lote.'=>'Sorta honetan prozesatutako guneak.','Sitios de la red que se sincronizan.'=>'Sinkronizatzen diren sareko guneak.','Valor de offset del siguiente lote.'=>'Hurrengo sortaren offset balioa.','Si este es el último lote.'=>'Hau azken sorta den ala ez.','Fichas creadas.'=>'Sortutako fitxak.','Fichas actualizadas.'=>'Eguneratutako fitxak.','Fichas creadas a mano reutilizadas.'=>'Berrerabilitako eskuz sortutako fitxak.','Fichas omitidas porque están en la papelera.'=>'Zakarrontzian daudelako saltatutako fitxak.','Autores de fichas que han recibido el rol Autor en el sitio principal.'=>'Gune nagusian Egilea rola jaso duten fitxen egileak.','Fichas sincronizadas en este lote.'=>'Sorta honetan sinkronizatutako fitxak.','Fichas cuyo sitio de origen ya no existe (solo en el último lote).'=>'Jatorrizko gunerik jada ez duten fitxak (azken sortan soilik).','taxonomy general nameEtapas Educativas'=>'Hezkuntza-etapak','taxonomy singular nameEtapa Educativa'=>'Hezkuntza-etapa','Buscar etapas educativas'=>'Bilatu hezkuntza-etapak','Todas las etapas'=>'Etapa guztiak','Etapa superior'=>'Etapa gurasoa','Etapa superior:'=>'Etapa gurasoa:','Editar etapa'=>'Editatu etapa','Actualizar etapa'=>'Eguneratu etapa','Añadir nueva etapa educativa'=>'Gehitu hezkuntza-etapa berria','Nombre de nueva etapa'=>'Etapa berriaren izena','Etapas Educativas'=>'Hezkuntza-etapak','taxonomy general nameIdiomas'=>'Hizkuntzak','taxonomy singular nameIdioma'=>'Hizkuntza','Buscar idiomas'=>'Bilatu hizkuntzak','Todos los idiomas'=>'Hizkuntza guztiak','Editar idioma'=>'Editatu hizkuntza','Actualizar idioma'=>'Eguneratu hizkuntza','Añadir nuevo idioma'=>'Gehitu hizkuntza berria','Nombre del nuevo idioma'=>'Hizkuntza berriaren izena','taxonomy general nameTemas de Interés'=>'Intereseko gaiak','taxonomy singular nameTema de Interés'=>'Intereseko gaia','Buscar temas'=>'Bilatu gaiak','Todos los temas'=>'Gai guztiak','Editar tema'=>'Editatu gaia','Actualizar tema'=>'Eguneratu gaia','Añadir nuev